import math

def Q(n):
    """Defines the polynomial Q(x) = x^3 - x + 1."""
    return n**3 - n + 1

def is_perfect_square(k):
    """Checks if an integer k is a perfect square."""
    if k < 0:
        return False
    root = int(math.sqrt(k))
    return root * root == k

print("--- Checking Q(n) = n^3 - n + 1 for n in [-10, 20] ---")

for n in range(-10, 21):
    value = Q(n)
    is_sq = is_perfect_square(value)

    # Special handling for the target values A=0, B=1
    if n == 0 or n == 1:
        print(f"n={n}: Q({n}) = {value} (Square: {is_sq}) [Expected Square]")
    elif is_sq:
        print(f"n={n}: Q({n}) = {value} (Square: {is_sq}) [UNEXPECTED SQUARE]")
    else:
        print(f"n={n}: Q({n}) = {value} (Square: {is_sq})")

print("\n--- Summary ---")
print("Values where Q(n) is a square (n != 0, 1):")
squares_found = [n for n in range(-10, 21) if n != 0 and n != 1 and is_perfect_square(Q(n))]
if squares_found:
    for n in squares_found:
        print(f"n={n}, Q(n)={Q(n)}")
else:
    print("No unexpected squares found in the range [-10, 20].")
